{
  "probability": 0.47,
  "range_low": 0.39,
  "range_high": 0.55,
  "summary": [
    "Posterior probability for any party or coalition achieving a 2/3 majority (134+ seats) in 2026 Hungary is 0.47, updating from a low anchor around 0.08.",
    "Key drivers push the posterior up: unified anti-Fidesz momentum around TISZA and potential district-level advantages in Hungary's mixed electoral system.",
    "Significant uncertainty remains due to divergent polls and a large undecided share, plus fragmentation risk that could hinder or help different coalitions."
  ],
  "confidence": "medium",
  "narrative": "Starting from a conservative anchor tied to the reference class of a two-thirds majority, updates from anti-Fidesz momentum, district-level seat dynamics, and poll volatility yield a 47% posterior probability. The outcome remains sensitive to turnout and how votes translate into seats, with substantial still-possible variation reflected in the calibrated range.",
  "justification": {
    "anchor": {
      "probability": 0.08,
      "basis": "reference class: Two-thirds majority (133+ seats) under Hungary's current mixed electoral framework; baseline prior probability drawn from historical prevalence of large-party seat share and varied polling outcomes."
    },
    "factor_updates": [
      {
        "factor": "Unified anti-Fidesz bid led by TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early 2026 polls show TISZA leading or closing gaps, increasing chances that an anti-Fidesz bloc could reach 134+ seats, though not guaranteed."
      },
      {
        "factor": "Electoral-system advantages for the largest party in single-member districts",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Hungary's mixed-member majoritarian system can amplify seat share from district results, potentially pushing totals toward 2/3 even without a national majority."
      },
      {
        "factor": "Poll divergence and turnout/undecided-voter uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent firm-level polls and sizable undecideds inject uncertainty about translating national support into seats; the net directional impact is ambiguous."
      },
      {
        "factor": " Gerrymandering/district-boundary effects",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "District boundary manipulation and local-race dynamics could tilt seat counts in favor of incumbents or a coalition, affecting 134+ seat prospects."
      },
      {
        "factor": "Opposition fragmentation risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "If smaller opposition parties enter Parliament or split votes, the anti-Fidesz bloc could be weakened, reducing the odds of reaching 134+ seats."
      }
    ],
    "synthesis_rationale": "Starting from an 8% anchor, cumulative updates from momentum, district-level advantages, and structural effects raise the posterior toward 0.47. Correlations among factors (e.g., momentum and district advantages) are acknowledged, and the calibration incorporates residual uncertainty from polling divergence and turnout variability, yielding a balanced posterior with a modest range."
  }
}

